const fs = require('fs');
const strip = (s) => s
  .replace(/: Record<string, string>/g, '')
  .replace(/: number/g, '')
  .replace(/: string/g, '');
const money = strip(fs.readFileSync('src/money.ts', 'utf8'));
const pricing = strip(fs.readFileSync('src/pricing.ts', 'utf8'));
eval(money + pricing);
const currencies = ['USD', 'EUR', 'GBP', 'CHF', ''];
const amounts = [0, -0, 1, 5, 50, 99, 100, 101, 999, 1000, 12345, -501, -100000, 123456789, 999999999, 1e9, NaN];
let mismatches = 0;
for (const a of amounts) for (const c of currencies) {
  const x = formatMoney(a, c), y = formatPrice(a, c);
  if (x !== y) { mismatches++; console.log('MISMATCH', a, c, JSON.stringify(x), JSON.stringify(y)); }
}
console.log('compared', amounts.length * currencies.length, 'cases; mismatches:', mismatches);
"

